import{_ as n,o as i,c as r,a3 as t}from"./chunks/framework.B9qR_F1m.js";const s="/bilder/teilen-server.jpg",a="/bilder/verwaltung.jpg",m=JSON.parse('{"title":"Mission teilen","description":"","frontmatter":{},"headers":[],"relativePath":"gemeinsam/teilen.md","filePath":"gemeinsam/teilen.md"}'),l={name:"gemeinsam/teilen.md"};function d(o,e,h,u,g,p){return i(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="mission-teilen" tabindex="-1">Mission teilen <a class="header-anchor" href="#mission-teilen" aria-label="Permalink to &quot;Mission teilen&quot;">​</a></h1><p>Allein planen geht mit der Desktop-App. Für eine ganze Gruppe legst du die Mission auf einen <strong>Shardwing-Server</strong>: Piloten holen sich per Link einen Platz, planen ihren Flight selbst, und alle sehen Änderungen live.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Designer                   Server                        Piloten</span></span>
<span class="line"><span>   │  Teilen ───────────►  Mission + Plätze  ◄─────────── Anmeldeseite (Link)</span></span>
<span class="line"><span>   │  ◄── Designer-Link       │                          │  Platz wählen, Name</span></span>
<span class="line"><span>   │                          │  ─── persönlicher Link ─►│</span></span>
<span class="line"><span>   │  ◄─── Live-Updates ───►  │  ◄─── Live-Updates ────► │</span></span>
<span class="line"><span>   │  Speichern → .miz        │</span></span></code></pre></div><h2 id="mission-auf-den-server-legen" tabindex="-1">Mission auf den Server legen <a class="header-anchor" href="#mission-auf-den-server-legen" aria-label="Permalink to &quot;Mission auf den Server legen&quot;">​</a></h2><ol class="steps"><li>Mission öffnen und oben auf <b>Teilen</b>.</li><li>In der Desktop-App die <b>Server-Adresse</b> eintragen (z. B. <code>https://shardwing.example.org</code>). Im Browser entfällt das – dort ist der Server die Seite selbst.</li><li>Den <b>Master-Schlüssel des Servers</b> eintragen, falls der Server einen hat. Den bekommst du vom Betreiber.</li><li><b>Auf den Server legen.</b> Shardwing lädt die .miz hoch – mitsamt allem, was du schon geplant hast – und öffnet sie als Designer.</li></ol><p>Ab jetzt gibt es keinen Speichern-Knopf mehr: Jede Änderung geht automatisch an den Server. Oben steht der Status – <em>Gespeichert</em>, <em>Speichert …</em> oder <em>Offline – Änderungen bleiben hier</em>.</p><h2 id="die-links" tabindex="-1">Die Links <a class="header-anchor" href="#die-links" aria-label="Permalink to &quot;Die Links&quot;">​</a></h2><p>In der <a href="/bereiche/uebersicht">Übersicht</a> unter <strong>Paket → Server</strong> findest du:</p><p><img src="`+s+'" alt="Paket → Server als Designer: Anmeldeseite, weitere Links, Einreichungen, Mission und Speicherdauer" loading="lazy"></p><table tabindex="0"><thead><tr><th>Link</th><th>Für wen</th><th>Hinweis</th></tr></thead><tbody><tr><td><strong>Anmeldeseite für die Piloten</strong></td><td>alle Piloten</td><td>Den verschickst du, z. B. im Discord.</td></tr><tr><td><strong>Designer-Link</strong></td><td>dich</td><td><strong>Geheim halten</strong> – wer ihn hat, ist Designer.</td></tr><tr><td><strong>Zuschauer-Link</strong></td><td>Gäste, Briefing-Leinwand</td><td>Nur lesen, Übersicht, nur Intel für alle.</td></tr></tbody></table><p>In diesem Browser öffnet jeder Link deine eigene Sitzung. Zum Ausprobieren als Pilot ein privates Fenster nehmen – oder lokal die <a href="./rollen#ansicht-als">Rollen-Ansicht</a> nutzen.</p><h2 id="piloten-verwalten" tabindex="-1">Piloten verwalten <a class="header-anchor" href="#piloten-verwalten" aria-label="Permalink to &quot;Piloten verwalten&quot;">​</a></h2><p>Unter <strong>Piloten</strong> siehst du jeden Platz: frei oder mit Namen. Pro Platz:</p><ul><li><strong>Neuer Link</strong> – der alte gilt nicht mehr (wenn ein Link in falsche Hände geraten ist).</li><li><strong>Austragen</strong> – Link, persönliche CMDS/Farben und Notizen werden gelöscht, der Platz ist wieder frei.</li><li><strong>Zurücksetzen</strong> – Route, DTC und Lineup Card des Flights zurück auf den Ausgangsstand.</li></ul><h2 id="einreichungen" tabindex="-1">Einreichungen <a class="header-anchor" href="#einreichungen" aria-label="Permalink to &quot;Einreichungen&quot;">​</a></h2><p><strong>Selbst prüfen</strong> anhaken, und Änderungen der Flights gehen nicht sofort in die Mission, sondern als <strong>Einreichung</strong> an dich. Du nimmst sie an oder lehnst sie mit Kommentar ab. Die Lineup Card geht immer durch.</p><p>Ohne den Haken übernimmt Shardwing alles, was die <a href="./rollen#freigaben">Freigaben</a> erlauben, direkt.</p><h2 id="mission-herunterladen-und-neu-starten" tabindex="-1">Mission herunterladen und neu starten <a class="header-anchor" href="#mission-herunterladen-und-neu-starten" aria-label="Permalink to &quot;Mission herunterladen und neu starten&quot;">​</a></h2><ul><li><strong>Aktuelle .miz</strong> – der geplante Stand, fertig für DCS. Der Server baut sie nach jeder Änderung kurz danach neu.</li><li><strong>Original-.miz</strong> – so, wie du sie hochgeladen hast.</li><li><strong>Ausgangsstand übernehmen</strong> – der aktuelle Stand wird zum Ziel von „Zurücksetzen“.</li><li><strong>Planung neu starten</strong> – alle Plätze werden frei, alle Flight-Änderungen verworfen.</li></ul><h2 id="speicherdauer-und-loschen" tabindex="-1">Speicherdauer und Löschen <a class="header-anchor" href="#speicherdauer-und-loschen" aria-label="Permalink to &quot;Speicherdauer und Löschen&quot;">​</a></h2><p>Eine geteilte Mission bleibt nicht für immer auf dem Server. Unter <strong>Speicherdauer</strong> steht, wann sie gelöscht wird:</p><ul><li><strong>30 Tage nach der letzten Änderung.</strong> Jede Änderung, auch von einem Piloten, schiebt den Termin nach hinten.</li><li><strong>Eine Woche nach dem Missionsdatum</strong>, wenn der Server-Betreiber eines eingetragen hat.</li></ul><p><strong>Vom Server löschen …</strong> entfernt die Mission sofort mit Planung, Plätzen und Kneeboards. Speicher vorher mit <strong>Vorher aktuelle .miz speichern</strong> den Stand, dann tipp zur Bestätigung den Namen der Mission ein. Alle Links werden ungültig; wer die Mission gerade offen hat, bekommt einen Hinweis und landet auf dem Startbildschirm.</p><div class="tip custom-block"><p class="custom-block-title">Für Server-Betreiber</p><p>Der Server sichert jede Mission mit Verlauf: Original, aktueller Stand, Historie (komprimiert) und ein Änderungsjournal. Ein Backup des Datenordners ist alles, was gesichert werden muss. Abgelaufene Missionen löscht er alle zehn Minuten selbst.</p><p><strong>Server-Verwaltung:</strong> Unter <code>https://dein-server/#/admin</code> meldest du dich mit dem Master-Schlüssel an. Dort siehst du alle Missionen mit Größe, Piloten und Löschtermin, dazu freien Speicher und Arbeitsspeicher. Du trägst das Missionsdatum ein, verlängerst eine Mission um 30 Tage, kopierst den Designer-Link oder löschst sie. Aus der App heraus kommst du auch ohne Adresse hin: Shardwing-Menü öffnen und unten auf die Versionsnummer doppelklicken. In der Desktop-App trägst du dabei zusätzlich die Server-Adresse ein. Nach der ersten Anmeldung steht <strong>Server-Verwaltung</strong> direkt im Shardwing-Menü.</p><p><img src="'+a+'" alt="Server-Verwaltung mit Missionen, Speicher und Löschterminen" loading="lazy"></p></div><h2 id="desktop-app-und-server" tabindex="-1">Desktop-App und Server <a class="header-anchor" href="#desktop-app-und-server" aria-label="Permalink to &quot;Desktop-App und Server&quot;">​</a></h2><p>Die Desktop-App ist beim Teilen nur Client. Server-Links öffnest du dort mit <strong>Link öffnen</strong> (<kbd>⌘L</kbd> / <kbd>Strg+L</kbd>); die App merkt sich die Server-Adresse.</p>',26)])])}const b=n(l,[["render",d]]);export{m as __pageData,b as default};
